#!/bin/zsh
set -euo pipefail
native_dir="${0:A:h}"
mkdir -p "$native_dir/build"
calendar_objects="$(mktemp -d "$native_dir/build/calendar-payload-objects.XXXXXX")"
trap 'rm -rf "$calendar_objects"' EXIT
calendar_sdk="$(xcrun --show-sdk-path)"
clang -O2 -I"$calendar_sdk/usr/include/libxml2" -c "$native_dir/CampaignHTML.c" -o "$calendar_objects/CampaignHTML.o"
clang -O2 -c "$native_dir/NativeMailTransport.c" -o "$calendar_objects/NativeMailTransport.o"
node "$native_dir/calendly-reference.cjs"
swiftc -D CALENDLY_SUBSCRIPTION_TESTS -D CALENDLY_RUNTIME_TESTS -swift-version 5 -parse-as-library -O -framework Security -framework Network -lsqlite3 -lxml2 -lcurl -import-objc-header "$native_dir/NativeMailParsing.h" "$calendar_objects/CampaignHTML.o" "$calendar_objects/NativeMailTransport.o" "$native_dir/NativeDatabase.swift" "$native_dir/CRMModules.swift" "$native_dir/InvoiceModules.swift" "$native_dir/CatalogModules.swift" "$native_dir/LineItemModules.swift" "$native_dir/LineItemMath.swift" "$native_dir/CRMLineItems.swift" "$native_dir/CRMCatalog.swift" "$native_dir/ProductCSV.swift" "$native_dir/PricingEngine.swift" "$native_dir/CRMService.swift" "$native_dir/OrderModules.swift" "$native_dir/OrderWorkflow.swift" "$native_dir/OrderDraftStore.swift" "$native_dir/CRMOrders.swift" "$native_dir/InvoiceMath.swift" "$native_dir/CRMRelationships.swift" "$native_dir/CRMProjects.swift" "$native_dir/CRMProjectTasks.swift" "$native_dir/CRMProjectKanban.swift" "$native_dir/CRMTemplates.swift" "$native_dir/CampaignMergeTags.swift" "$native_dir/CampaignWorkflow.swift" "$native_dir/CRMCampaigns.swift" "$native_dir/MailReview.swift" "$native_dir/CRMCampaignDelivery.swift" "$native_dir/CampaignOperations.swift" "$native_dir/CampaignDispatch.swift" "$native_dir/InvoiceMail.swift" "$native_dir/InvoiceMailCredentials.swift" "$native_dir/CampaignHTML.swift" "$native_dir/CampaignMail.swift" "$native_dir/CampaignMailWorker.swift" "$native_dir/CampaignWebhook.swift" "$native_dir/CampaignPublicHTTP.swift" "$native_dir/CampaignRelayClient.swift" "$native_dir/CampaignRelaySync.swift" "$native_dir/CampaignRelayCredentials.swift" "$native_dir/CampaignRuntime.swift" "$native_dir/NativeCalendarEvents.swift" "$native_dir/NativeCalendarResponse.swift" "$native_dir/NativeMail.swift" "$native_dir/NativeMailTemporaryFiles.swift" "$native_dir/NativeFreshCredentialPublication.swift" "$native_dir/GoogleCalendarCredentials.swift" "$native_dir/NativeUserCredentialCleanup.swift" "$native_dir/GoogleCalendarOAuth.swift" "$native_dir/GoogleCalendarLoopback.swift" "$native_dir/GoogleCalendarSpool.swift" "$native_dir/GoogleCalendarSync.swift" "$native_dir/GoogleCalendarOutbound.swift" "$native_dir/GoogleCalendarPushWorker.swift" "$native_dir/CalendlyWebhook.swift" "$native_dir/CalendlyRelayClient.swift" "$native_dir/CalendlyRelaySync.swift" "$native_dir/CalendlyRelayTests.swift" "$native_dir/CalendlyAPI.swift" "$native_dir/CalendlyCredentials.swift" "$native_dir/CalendlySubscription.swift" "$native_dir/CalendlySubscriptionTests.swift" "$native_dir/CalendlyJobs.swift" "$native_dir/CalendlyRuntimeTests.swift" -o "$native_dir/build/CalendlyRuntimeTests"
"$native_dir/build/CalendlyRuntimeTests" "$native_dir" "$@"
